<script setup lang="ts">
import {ref,computed,onMounted} from 'vue';import {useRoute} from 'vue-router';import PageHeader from '@/components/shared/PageHeader.vue';import BaseBadge from '@/components/base/BaseBadge.vue';import {useTicketStore} from '@/stores/tickets';import {useAppStore} from '@/stores/app';import {ReportService} from '@/services';import {Plus,Search,ChevronLeft,ChevronRight,Download,MoreHorizontal,Trash2,Eye} from 'lucide-vue-next';
const store=useTicketStore(),app=useAppStore(),route=useRoute(),selected=ref<number[]>([]),page=ref(1),pageSize=ref(5),menu=ref<number|null>(null);const statuses=['Todos','Aberto','Aguardando triagem','Em atendimento','Aguardando funcionário','Aguardando peça','Agendado','Resolvido'];const pages=computed(()=>Math.max(1,Math.ceil(store.filtered.length/pageSize.value)));const rows=computed(()=>store.filtered.slice((page.value-1)*pageSize.value,page.value*pageSize.value));
onMounted(()=>{if(route.query.q)store.query=String(route.query.q);if(route.query.status)store.status=String(route.query.status);if(route.query.priority)store.priority=String(route.query.priority)});
function remove(id:number){if(confirm('Excluir este chamado? Esta ação removerá o registro local.')){store.remove(id);menu.value=null;app.toast('Chamado excluído','O registro foi removido do protótipo.','warning')}}function exportPdf(){ReportService.exportPdf('Chamados',['Protocolo','Título','Prioridade','Status'],store.filtered.map(t=>[t.protocol,t.title,t.priority,t.status]));app.toast('Relatório gerado','O PDF de chamados foi baixado.')}
</script>
<template><PageHeader title="Chamados" description="Gerencie solicitações, prazos e atendimentos da equipe"><button class="btn btn-primary" @click="app.ticketModalOpen=true"><Plus class="size-4"/>Novo chamado <kbd class="ml-1 text-[9px] opacity-70">Ctrl N</kbd></button></PageHeader><div class="mb-3 grid grid-cols-4 gap-3"><div v-for="s in [['Abertos',3,'text-blue-600'],['Críticos',2,'text-red-600'],['Em atendimento',1,'text-violet-600'],['Resolvidos no mês',34,'text-emerald-600']]" :key="String(s[0])" class="card p-3"><div class="text-xs text-slate-500">{{s[0]}}</div><div class="mt-1 text-xl font-bold" :class="s[2]">{{s[1]}}</div></div></div><div class="card"><div class="flex items-center gap-2 border-b p-3 dark:border-slate-700"><div class="relative w-64"><Search class="absolute left-3 top-2.5 size-4 text-slate-400"/><input v-model="store.query" class="field pl-9" placeholder="Protocolo" @input="page=1"/></div><select v-model="store.status" class="field w-48" @change="page=1"><option v-for="s in statuses" :key="s">{{s}}</option></select><select v-model="store.priority" class="field w-36" @change="page=1"><option>Todas</option><option>Baixa</option><option>Média</option><option>Alta</option><option>Crítica</option></select><button class="btn btn-secondary ml-auto" @click="exportPdf"><Download class="size-4"/>Exportar PDF</button></div><div v-if="selected.length" class="flex items-center gap-3 bg-blue-50 px-4 py-2 text-xs text-blue-800 dark:bg-blue-950"><b>{{selected.length}} selecionados</b><button @click="selected.forEach(id=>store.update(id,{status:'Em atendimento'}));selected=[]">Iniciar atendimento</button><button @click="selected.forEach(id=>store.update(id,{technician:'Lucas Almeida'}));selected=[]">Atribuir a mim</button><button class="text-red-600" @click="selected.forEach(id=>store.remove(id));selected=[]">Excluir</button></div><div class="overflow-visible"><table class="w-full min-w-[1050px] text-left text-xs"><thead class="table-head"><tr><th class="w-10 px-4 py-3"><input type="checkbox" @change="selected=($event.target as HTMLInputElement).checked?rows.map(t=>t.id):[]"/></th><th>Protocolo</th><th class="w-[30%]">Título / Solicitante</th><th>Setor</th><th>Prioridade</th><th>Status</th><th>Técnico</th><th>Prazo</th><th class="w-10"></th></tr></thead><tbody><tr v-for="t in rows" :key="t.id" class="border-t border-slate-100 hover:bg-slate-50 dark:border-slate-700 dark:hover:bg-slate-700/30"><td class="px-4 py-3"><input v-model="selected" type="checkbox" :value="t.id"/></td><td><router-link :to="`/chamados/${t.id}`" class="font-mono font-semibold text-blue-600">{{t.protocol}}</router-link><div class="text-[10px] text-slate-400">{{t.channel}}</div></td><td class="py-3"><router-link :to="`/chamados/${t.id}`" class="font-semibold hover:text-blue-600">{{t.title}}</router-link><div class="mt-0.5 text-[11px] text-slate-500">{{t.requester}} · {{t.equipment}}</div></td><td>{{t.department}}</td><td><BaseBadge :label="t.priority"/></td><td><BaseBadge :label="t.status"/></td><td>{{t.technician}}</td><td>{{t.deadline.split(' ')[0]}}</td><td class="relative"><button class="rounded p-1 hover:bg-slate-200" @click="menu=menu===t.id?null:t.id"><MoreHorizontal class="size-4"/></button><div v-if="menu===t.id" class="card absolute right-5 top-8 z-20 w-36 p-1 shadow-lg"><router-link :to="`/chamados/${t.id}`" class="flex items-center gap-2 rounded px-3 py-2 hover:bg-slate-50 dark:hover:bg-slate-700"><Eye class="size-3"/>Abrir</router-link><button class="flex w-full items-center gap-2 rounded px-3 py-2 text-red-600 hover:bg-red-50" @click="remove(t.id)"><Trash2 class="size-3"/>Excluir</button></div></td></tr></tbody></table></div><div class="flex items-center justify-between border-t p-3 text-xs text-slate-500 dark:border-slate-700"><div>Mostrando {{rows.length}} de {{store.filtered.length}} <select v-model="pageSize" class="ml-2 rounded border bg-transparent p-1" @change="page=1"><option :value="5">5 por página</option><option :value="10">10 por página</option></select></div><div class="flex items-center gap-1"><button class="btn btn-secondary !size-8 !p-0" :disabled="page===1" @click="page--"><ChevronLeft class="size-4"/></button><button v-for="p in pages" :key="p" class="btn !size-8 !p-0" :class="page===p?'btn-primary':'btn-secondary'" @click="page=p">{{p}}</button><button class="btn btn-secondary !size-8 !p-0" :disabled="page===pages" @click="page++"><ChevronRight class="size-4"/></button></div></div></div></template>
